@Override
public synchronized Optional<SessionDocument> load(String sessionId) {
    State state = sessions.get(sessionId);
    return state == null || state.document.execution().status() != CanonicalSessionState.SessionStatus.AVAILABLE
            ? Optional.empty() : Optional.of(state.document);
}

@Override
public synchronized List<SessionDocument.Metadata> list() {
    return sessions.values().stream()
            .filter(state -> state.document.execution().status()
                    == CanonicalSessionState.SessionStatus.AVAILABLE)
            .map(state -> state.document.metadata())
            .sorted(Comparator.comparing(SessionDocument.Metadata::createdAt).reversed()).toList();
}

@Override
public synchronized SummaryPage listSummaries(SummaryQuery query) {
    List<SessionSummary> summaries = sessions.values().stream()
            .filter(state -> state.document.execution().status()
                    == CanonicalSessionState.SessionStatus.AVAILABLE)
            .map(state -> SessionSummary.from(state.document))
            .sorted(SessionRepository::compare).toList();
    return SessionRepository.page(summaries, query);
